def decode_to_file(base64_text: str, output_path: str) -> None:
    clean = "".join(base64_text.split())
    data = base64.b64decode(clean.encode("utf-8"))
    Path(output_path).parent.mkdir(parents=True, exist_ok=True)
    Path(output_path).write_bytes(data)
    print(f"Wrote {output_path}")


if __name__ == "__main__":
    decode_to_file(README_B64, "README.md")
    decode_to_file(RAPPORT_B64, "docs/rapport_technique.md")